#!/usr/bin/env python3
"""Compare pinned protocol data with reports generated by the exact 1.21 JAR."""
import argparse
import hashlib
import json
from pathlib import Path

PROJECT=Path(__file__).resolve().parents[1]
INNER_SHA='8d47de9a76ab47186deba6c9beda6f9345c6f73618fa5a157c57608be0505a01'


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--oracle-dir',type=Path,default=PROJECT.parent/'mc121-oracle')
    args=parser.parse_args()
    oracle=args.oracle_dir.resolve()
    jar=oracle/'server-inner-1.21.jar'
    actual=hashlib.sha256(jar.read_bytes()).hexdigest()
    if actual!=INNER_SHA:raise ValueError('This comparison requires the exact official 1.21 inner JAR')
    directory=oracle/'reports/reports'
    paths={name:directory/(name+'.json') for name in ['items','blocks','registries']}
    reports={name:json.loads(path.read_text()) for name,path in paths.items()}
    catalog_path=PROJECT/'fixtures/items-1.21.json'
    catalog=json.loads(catalog_path.read_text())
    errors=[]
    count_items=0
    for name,entry in reports['registries']['minecraft:item']['entries'].items():
        local=catalog['items'].get(str(entry['protocol_id']))
        if not local or 'minecraft:'+local['name']!=name:errors.append('item registry identity: '+name)
        else:
            prototype=reports['items'][name]['components']
            if local['stack_size']!=prototype.get('minecraft:max_stack_size',1):errors.append('max stack size: '+name)
            if local['max_damage']!=prototype.get('minecraft:max_damage'):errors.append('max damage: '+name)
            count_items+=1
    if count_items!=len(catalog['items']):errors.append('item registry count')
    count_components=0
    for name,entry in reports['registries']['minecraft:data_component_type']['entries'].items():
        local=catalog['component_types'].get(str(entry['protocol_id']))
        if not local or 'minecraft:'+local['name']!=name:errors.append('component registry identity: '+name)
        else:count_components+=1
    if count_components!=len(catalog['component_types']):errors.append('component registry count')
    count_blocks=0;count_states=0
    for name,block in reports['blocks'].items():
        local=catalog['blocks'].get(name.removeprefix('minecraft:'))
        if not local:errors.append('block identity: '+name);continue
        states=block['states'];ids=[state['id'] for state in states]
        default=next(state['id'] for state in states if state.get('default'))
        if min(ids)!=local['min_state'] or max(ids)!=local['max_state'] or default!=local['default_state']:
            errors.append('state boundaries/default: '+name)
        for state in states:
            offset=state['id']-local['min_state'];decoded={}
            for prop in reversed(local['properties']):
                index=offset%prop['num_values'];offset//=prop['num_values']
                values=prop.get('values') or (['true','false'] if prop['type']=='bool' else list(map(str,range(prop['num_values']))))
                decoded[prop['name']]=str(values[index])
            if offset or decoded!=state.get('properties',{}):errors.append('state properties: '+name+'/'+str(state['id']))
            count_states+=1
        count_blocks+=1
    if count_blocks!=len(catalog['blocks']):errors.append('block registry count')
    result={'ok':not errors,'minecraft':'1.21','protocol':767,'oracle_inner_sha256':actual,
            'method':'Exact official JAR net.minecraft.data.Main --reports, compared before attaching prototype data',
            'items':count_items,'components':count_components,'blocks':count_blocks,'block_states':count_states,
            'report_sha256':{name:hashlib.sha256(path.read_bytes()).hexdigest() for name,path in paths.items()},
            'differences':errors[:100]}
    (PROJECT/'tools/inventory_report_conformance.json').write_text(json.dumps(result,indent=2)+'\n')
    if errors:raise ValueError('Official 1.21 registry/state differences: '+str(errors[:20]))
    for name,entry in reports['registries']['minecraft:item']['entries'].items():
        catalog['items'][str(entry['protocol_id'])]['prototype_components']=reports['items'][name]['components']
    catalog['source']['oracle']={key:result[key] for key in ['minecraft','oracle_inner_sha256','report_sha256']}
    catalog_path.write_text(json.dumps(catalog,separators=(',',':'))+'\n')
    print(json.dumps(result,indent=2))


if __name__=='__main__':main()
